<?php if($makeups):?><hr><h3 class="h6">Reposições</h3><div class="table-responsive"><table class="table"><thead><tr><th>Aluno</th><th>Falta</th><th>Status</th><th>Agendar</th></tr></thead><tbody><?php foreach($makeups as $m):?><tr><td><?=$e($m['student_name'])?></td><td><?=date('d/m/Y',strtotime($m['original_date']))?></td><td><?=$e($m['status'])?><?php if($m['replacement_date']):?> · <?=date('d/m/Y',strtotime($m['replacement_date']))?><?php endif;?></td><td><?php if($m['status']==='credit'):?><form class="d-flex gap-1" method="post" action="/sports/classes/makeups/<?=(int)$m['id']?>/schedule"><?=CSRF::field()?><select class="form-select form-select-sm" name="replacement_class_id"><?php foreach($classes as $cl):?><option value="<?=(int)$cl['id']?>"><?=$e($cl['name'])?></option><?php endforeach;?></select><input class="form-control form-control-sm" type="date" name="replacement_date" required><button class="btn btn-sm btn-outline-primary">Agendar</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
